-- AtomGo v1.0.0 schema baseline (squashed from migrations 0001..0056).
-- Generated by cmd/squashgen; idempotent (IF NOT EXISTS), safe to re-run.

CREATE TABLE IF NOT EXISTS "ai_config" (
    "id" INTEGER PRIMARY KEY,
    "provider" TEXT NOT NULL DEFAULT '',
    "base_url" TEXT NOT NULL DEFAULT '',
    "model" TEXT NOT NULL DEFAULT '',
    "api_key_ciphertext" BLOB,
    "budget_json" TEXT NOT NULL DEFAULT '{"monthlyTokenLimit":null}',
    "enabled" INTEGER NOT NULL DEFAULT 0,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "anomaly_alerts" (
    "id" TEXT PRIMARY KEY,
    "server_id" TEXT NOT NULL,
    "server_name" TEXT NOT NULL,
    "metric" TEXT NOT NULL,
    "operator" TEXT NOT NULL,
    "threshold" REAL NOT NULL,
    "value" REAL NOT NULL,
    "message" TEXT NOT NULL,
    "created_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "anomaly_rules" (
    "id" TEXT PRIMARY KEY,
    "metric" TEXT NOT NULL,
    "operator" TEXT NOT NULL,
    "threshold" REAL NOT NULL,
    "server_id" TEXT,
    "enabled" INTEGER NOT NULL DEFAULT 1,
    "created_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "audit_log" (
    "id" TEXT PRIMARY KEY,
    "timestamp" TEXT NOT NULL,
    "actor" TEXT NOT NULL,
    "action" TEXT NOT NULL,
    "target_type" TEXT NOT NULL,
    "target_id" TEXT,
    "detail_json" TEXT NOT NULL DEFAULT '{}',
    "ip" TEXT,
    "created_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "credentials" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "scope" TEXT NOT NULL DEFAULT '',
    "ciphertext" BLOB NOT NULL,
    "masked_value" TEXT NOT NULL,
    "last_used_at" TEXT,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "username" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "custom_nodes" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "node_type" TEXT NOT NULL,
    "summary" TEXT NOT NULL DEFAULT '',
    "config_json" TEXT NOT NULL DEFAULT '{}',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "deploy_batch_items" (
    "id" TEXT PRIMARY KEY,
    "batch_id" TEXT NOT NULL,
    "item_index" INTEGER NOT NULL,
    "artifact_id" TEXT NOT NULL,
    "artifact_name" TEXT NOT NULL,
    "server_id" TEXT NOT NULL,
    "server_name" TEXT NOT NULL,
    "config_json" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "message" TEXT NOT NULL DEFAULT '',
    "attempt" INTEGER NOT NULL DEFAULT 0,
    "started_at" TEXT,
    "finished_at" TEXT,
    FOREIGN KEY ("batch_id") REFERENCES "deploy_batches" ("id") ON DELETE CASCADE,
    UNIQUE ("batch_id", "item_index", "server_id")
);

CREATE TABLE IF NOT EXISTS "deploy_batches" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "idempotency_key" TEXT NOT NULL,
    "request_hash" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE,
    UNIQUE ("run_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "deploy_targets" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "server_id" TEXT NOT NULL,
    "server_name" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "message" TEXT NOT NULL DEFAULT '',
    "started_at" TEXT NOT NULL,
    "finished_at" TEXT,
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id")
);

CREATE TABLE IF NOT EXISTS "diagnosis_feedback" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "verdict" TEXT NOT NULL,
    "correct_root_cause" TEXT NOT NULL DEFAULT '',
    "diagnosis_snapshot" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE,
    UNIQUE ("run_id")
);

CREATE TABLE IF NOT EXISTS "dns_providers" (
    "id" TEXT PRIMARY KEY,
    "type" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "credential_id" TEXT NOT NULL,
    "base_domain" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "metric_samples" (
    "id" TEXT PRIMARY KEY,
    "server_id" TEXT NOT NULL,
    "cpu_percent" REAL,
    "memory_percent" REAL,
    "disk_percent" REAL,
    "sampled_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "notification_channels" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "enabled" INTEGER NOT NULL DEFAULT 1,
    "config_json" TEXT NOT NULL DEFAULT '{}',
    "secret_ciphertext" BLOB,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "notification_routes" (
    "id" TEXT PRIMARY KEY,
    "project_id" TEXT,
    "event" TEXT NOT NULL,
    "channel_id" TEXT NOT NULL,
    "enabled" INTEGER NOT NULL DEFAULT 1,
    "created_at" TEXT NOT NULL,
    FOREIGN KEY ("channel_id") REFERENCES "notification_channels" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "notification_templates" (
    "id" TEXT PRIMARY KEY,
    "project_id" TEXT,
    "event" TEXT NOT NULL,
    "channel_id" TEXT,
    "title_template" TEXT NOT NULL DEFAULT '',
    "body_template" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    FOREIGN KEY ("channel_id") REFERENCES "notification_channels" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "notify_config" (
    "id" INTEGER PRIMARY KEY,
    "language" TEXT NOT NULL DEFAULT 'zh-CN',
    "updated_at" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "oauth_apps" (
    "provider" TEXT PRIMARY KEY,
    "client_id" TEXT NOT NULL DEFAULT '',
    "client_secret_ciphertext" BLOB,
    "base_url" TEXT NOT NULL DEFAULT '',
    "enabled" INTEGER NOT NULL DEFAULT 0,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "ops_chat_approvals" (
    "id" TEXT PRIMARY KEY,
    "session_id" TEXT NOT NULL,
    "run_id" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "instance_id" TEXT NOT NULL,
    "expires_at" BIGINT NOT NULL,
    "body" BLOB NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "ops_chat_runs" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("session_id") REFERENCES "ops_chat_sessions" ("id") ON DELETE CASCADE,
    UNIQUE ("run_id")
);

CREATE TABLE IF NOT EXISTS "ops_chat_calls" (
    "id" TEXT PRIMARY KEY,
    "session_id" TEXT NOT NULL,
    "run_id" TEXT NOT NULL,
    "server_id" TEXT NOT NULL,
    "tool_id" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "ordinal" INTEGER NOT NULL,
    "args_hash" TEXT NOT NULL,
    "target_hash" TEXT NOT NULL,
    "body" BLOB NOT NULL,
    "created_at" BIGINT NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "ops_chat_runs" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("session_id") REFERENCES "ops_chat_sessions" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "ops_chat_contexts" (
    "context_key" TEXT PRIMARY KEY,
    "session_id" TEXT NOT NULL,
    FOREIGN KEY ("session_id") REFERENCES "ops_chat_sessions" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "ops_chat_entries" (
    "session_id" TEXT NOT NULL,
    "seq" BIGINT NOT NULL,
    "kind" TEXT NOT NULL,
    "run_id" TEXT NOT NULL DEFAULT '',
    "call_id" TEXT NOT NULL DEFAULT '',
    "context_allowed" INTEGER NOT NULL DEFAULT 0,
    "visible" INTEGER NOT NULL DEFAULT 0,
    "body" BLOB NOT NULL,
    "body_size" INTEGER NOT NULL,
    "created_at" BIGINT NOT NULL,
    PRIMARY KEY ("session_id", "seq"),
    FOREIGN KEY ("session_id") REFERENCES "ops_chat_sessions" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "ops_chat_runs" (
    "id" TEXT PRIMARY KEY,
    "session_id" TEXT NOT NULL,
    "request_id" TEXT NOT NULL,
    "payload_hash" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "cancel_requested" INTEGER NOT NULL DEFAULT 0,
    "body" BLOB NOT NULL,
    "created_at" BIGINT NOT NULL,
    FOREIGN KEY ("session_id") REFERENCES "ops_chat_sessions" ("id") ON DELETE CASCADE,
    UNIQUE ("request_id")
);

CREATE TABLE IF NOT EXISTS "ops_chat_sessions" (
    "id" TEXT PRIMARY KEY,
    "revision" INTEGER NOT NULL,
    "seq" INTEGER NOT NULL DEFAULT 0,
    "visible_count" INTEGER NOT NULL DEFAULT 0,
    "body_bytes" INTEGER NOT NULL DEFAULT 0,
    "active_run" TEXT NOT NULL DEFAULT '',
    "body" BLOB NOT NULL,
    "created_at" BIGINT NOT NULL,
    "updated_at" BIGINT NOT NULL
);

CREATE TABLE IF NOT EXISTS "ops_chat_state" (
    "id" INTEGER PRIMARY KEY,
    "active_session" TEXT NOT NULL DEFAULT '',
    "lease_owner" TEXT NOT NULL DEFAULT '',
    "lease_until" BIGINT NOT NULL DEFAULT 0,
    "keycheck" BLOB NOT NULL
);

CREATE TABLE IF NOT EXISTS "pipeline_configs" (
    "project_id" TEXT PRIMARY KEY,
    "spec_json" TEXT NOT NULL DEFAULT '{}',
    "spec_yaml" TEXT NOT NULL DEFAULT '',
    "status" TEXT NOT NULL DEFAULT 'draft',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "saved_at" TEXT,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "pipeline_runs" (
    "id" TEXT PRIMARY KEY,
    "project_id" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'queued',
    "trigger_type" TEXT NOT NULL DEFAULT 'manual',
    "trigger_branch" TEXT NOT NULL DEFAULT '',
    "trigger_commit" TEXT NOT NULL DEFAULT '',
    "trigger_actor" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    "started_at" TEXT,
    "finished_at" TEXT,
    "resolved_environment" TEXT NOT NULL DEFAULT '',
    "resolved_target_server_ids" TEXT NOT NULL DEFAULT '[]',
    "failure_log" TEXT NOT NULL DEFAULT '',
    "diagnosis_json" TEXT NOT NULL DEFAULT '',
    "params_json" TEXT NOT NULL DEFAULT '{}',
    "chain_source_run_id" TEXT NOT NULL DEFAULT '',
    "chain_depth" INTEGER NOT NULL DEFAULT 0,
    "spec_source" TEXT NOT NULL DEFAULT '',
    "spec_source_ref" TEXT NOT NULL DEFAULT '',
    "spec_source_file" TEXT NOT NULL DEFAULT '',
    "spec_source_fallback" TEXT NOT NULL DEFAULT '',
    "execution_mode" TEXT NOT NULL DEFAULT 'pending',
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "pipeline_settings" (
    "project_id" TEXT PRIMARY KEY,
    "build_json" TEXT NOT NULL DEFAULT '{}',
    "environments_json" TEXT NOT NULL DEFAULT '[]',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "steps_json" TEXT NOT NULL DEFAULT '[]',
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "pipeline_templates" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "stages_json" TEXT NOT NULL DEFAULT '[]',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "pipeline_triggers" (
    "project_id" TEXT PRIMARY KEY,
    "webhook_token" TEXT NOT NULL,
    "webhook_secret_ciphertext" BLOB NOT NULL,
    "events_json" TEXT NOT NULL DEFAULT '{}',
    "branch_mappings_json" TEXT NOT NULL DEFAULT '[]',
    "unmatched_policy" TEXT NOT NULL DEFAULT 'record',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "path_filters_json" TEXT NOT NULL DEFAULT '[]',
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE,
    UNIQUE ("webhook_token")
);

CREATE TABLE IF NOT EXISTS "project_chain_targets" (
    "id" TEXT PRIMARY KEY,
    "project_id" TEXT NOT NULL,
    "downstream_project_id" TEXT NOT NULL,
    "branch" TEXT NOT NULL DEFAULT '',
    "enabled" INTEGER NOT NULL DEFAULT 1,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("downstream_project_id") REFERENCES "projects" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "project_concurrency" (
    "project_id" TEXT PRIMARY KEY,
    "max_concurrent" INTEGER NOT NULL DEFAULT 0,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "project_crons" (
    "project_id" TEXT PRIMARY KEY,
    "expression" TEXT NOT NULL DEFAULT '',
    "branch" TEXT NOT NULL DEFAULT '',
    "enabled" INTEGER NOT NULL DEFAULT 0,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "project_parameters" (
    "project_id" TEXT PRIMARY KEY,
    "defs_json" TEXT NOT NULL DEFAULT '[]',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "project_runners" (
    "project_id" TEXT PRIMARY KEY,
    "runner_server_id" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "projects" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "repo_url" TEXT NOT NULL,
    "default_branch" TEXT NOT NULL DEFAULT '',
    "credential_id" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "pac_enabled" INTEGER NOT NULL DEFAULT 0,
    "pr_status_enabled" INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY ("credential_id") REFERENCES "credentials" ("id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "proxy_routes" (
    "id" TEXT PRIMARY KEY,
    "server_id" TEXT NOT NULL,
    "domain" TEXT NOT NULL,
    "upstream_container" TEXT NOT NULL,
    "upstream_port" INTEGER NOT NULL,
    "tls_mode" TEXT NOT NULL DEFAULT 'auto',
    "enabled" INTEGER NOT NULL DEFAULT 1,
    "cert_status" TEXT NOT NULL DEFAULT 'pending',
    "cert_detail" TEXT,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "config" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "retention_config" (
    "id" INTEGER PRIMARY KEY,
    "enabled" INTEGER NOT NULL DEFAULT 0,
    "keep_per_project" INTEGER NOT NULL DEFAULT 0,
    "max_age_days" INTEGER NOT NULL DEFAULT 0,
    "updated_at" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "role_permissions" (
    "role" TEXT NOT NULL,
    "permission" TEXT NOT NULL,
    PRIMARY KEY ("role", "permission")
);

CREATE TABLE IF NOT EXISTS "run_approvals" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "stage_id" TEXT NOT NULL,
    "stage_name" TEXT NOT NULL DEFAULT '',
    "status" TEXT NOT NULL DEFAULT 'pending',
    "decided_by" TEXT NOT NULL DEFAULT '',
    "decided_at" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE,
    UNIQUE ("run_id", "stage_id")
);

CREATE TABLE IF NOT EXISTS "run_artifacts" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "reference" TEXT NOT NULL,
    "size_bytes" INTEGER NOT NULL DEFAULT 0,
    "metadata_json" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "run_logs" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "seq" INTEGER NOT NULL,
    "ts" TEXT NOT NULL,
    "stream" TEXT NOT NULL,
    "step_ordinal" INTEGER NOT NULL,
    "text" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "run_promotions" (
    "id" TEXT PRIMARY KEY,
    "project_id" TEXT NOT NULL,
    "source_run_id" TEXT NOT NULL,
    "from_environment" TEXT NOT NULL DEFAULT '',
    "target_environment" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'pending',
    "approval_stage" TEXT NOT NULL DEFAULT '',
    "promoted_by" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    "decided_at" TEXT NOT NULL DEFAULT '',
    "initiated_by" TEXT NOT NULL DEFAULT '',
    FOREIGN KEY ("source_run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "run_steps" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'pending',
    "ordinal" INTEGER NOT NULL DEFAULT 0,
    "started_at" TEXT,
    "finished_at" TEXT,
    "stage" TEXT NOT NULL DEFAULT '',
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "run_test_reports" (
    "id" TEXT PRIMARY KEY,
    "run_id" TEXT NOT NULL,
    "stage_id" TEXT NOT NULL DEFAULT '',
    "stage_name" TEXT NOT NULL DEFAULT '',
    "format" TEXT NOT NULL DEFAULT 'junit',
    "total" INTEGER NOT NULL DEFAULT 0,
    "passed" INTEGER NOT NULL DEFAULT 0,
    "failed" INTEGER NOT NULL DEFAULT 0,
    "skipped" INTEGER NOT NULL DEFAULT 0,
    "duration_sec" REAL NOT NULL DEFAULT 0,
    "coverage_pct" REAL NOT NULL DEFAULT -1,
    "gate_enabled" INTEGER NOT NULL DEFAULT 0,
    "gate_passed" INTEGER NOT NULL DEFAULT 1,
    "gate_reason" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    FOREIGN KEY ("run_id") REFERENCES "pipeline_runs" ("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "server_proxy_settings" (
    "server_id" TEXT PRIMARY KEY,
    "mode" TEXT NOT NULL DEFAULT 'managed',
    "external_config_path" TEXT NOT NULL DEFAULT '',
    "external_fragment_dir" TEXT NOT NULL DEFAULT '',
    "external_reload_cmd" TEXT NOT NULL DEFAULT '',
    "caddy_external_container" TEXT NOT NULL DEFAULT '',
    "caddy_network" TEXT NOT NULL DEFAULT '',
    "caddy_container" TEXT NOT NULL DEFAULT '',
    "caddy_data_volume" TEXT NOT NULL DEFAULT '',
    "caddy_config_volume" TEXT NOT NULL DEFAULT '',
    "updated_at" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "servers" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "host" TEXT NOT NULL,
    "port" INTEGER NOT NULL DEFAULT 22,
    "username" TEXT NOT NULL,
    "credential_id" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    FOREIGN KEY ("credential_id") REFERENCES "credentials" ("id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "sessions" (
    "token" TEXT PRIMARY KEY,
    "csrf_token" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "expires_at" TEXT NOT NULL,
    "last_seen_at" TEXT NOT NULL,
    "username" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "system_settings" (
    "key" TEXT PRIMARY KEY,
    "value" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "users" (
    "id" TEXT PRIMARY KEY,
    "username" TEXT NOT NULL,
    "password_hash" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'admin',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    UNIQUE ("username")
);

CREATE TABLE IF NOT EXISTS "variable_groups" (
    "id" TEXT PRIMARY KEY,
    "name" TEXT NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "vars_json" TEXT NOT NULL DEFAULT '[]',
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "webhook_deliveries" (
    "id" TEXT PRIMARY KEY,
    "project_id" TEXT NOT NULL,
    "delivery_id" TEXT NOT NULL,
    "event" TEXT NOT NULL DEFAULT '',
    "branch" TEXT NOT NULL DEFAULT '',
    "commit_sha" TEXT NOT NULL DEFAULT '',
    "run_id" TEXT NOT NULL DEFAULT '',
    "outcome" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL,
    FOREIGN KEY ("project_id") REFERENCES "projects" ("id") ON DELETE CASCADE,
    UNIQUE ("project_id", "delivery_id")
);

CREATE INDEX IF NOT EXISTS "idx_anomaly_alerts_created_at" ON "anomaly_alerts" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_anomaly_alerts_server_id" ON "anomaly_alerts" ("server_id");
CREATE INDEX IF NOT EXISTS "idx_audit_log_action" ON "audit_log" ("action");
CREATE INDEX IF NOT EXISTS "idx_audit_log_target_type" ON "audit_log" ("target_type");
CREATE INDEX IF NOT EXISTS "idx_audit_log_timestamp" ON "audit_log" ("timestamp", "id");
CREATE INDEX IF NOT EXISTS "idx_custom_nodes_name" ON "custom_nodes" ("name");
CREATE INDEX IF NOT EXISTS "idx_deploy_batch_items_batch" ON "deploy_batch_items" ("batch_id", "item_index");
CREATE INDEX IF NOT EXISTS "idx_deploy_batches_run" ON "deploy_batches" ("run_id", "created_at");
CREATE INDEX IF NOT EXISTS "idx_deploy_targets_run" ON "deploy_targets" ("run_id");
CREATE INDEX IF NOT EXISTS "idx_diagnosis_feedback_created_at" ON "diagnosis_feedback" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_dns_providers_type" ON "dns_providers" ("type");
CREATE INDEX IF NOT EXISTS "idx_metric_samples_server_time" ON "metric_samples" ("server_id", "sampled_at");
CREATE INDEX IF NOT EXISTS "idx_metric_samples_time" ON "metric_samples" ("sampled_at");
CREATE INDEX IF NOT EXISTS "idx_notification_routes_event" ON "notification_routes" ("event");
CREATE INDEX IF NOT EXISTS "idx_notification_templates_event" ON "notification_templates" ("event");
CREATE INDEX IF NOT EXISTS "idx_pipeline_runs_project_id" ON "pipeline_runs" ("project_id");
CREATE INDEX IF NOT EXISTS "idx_pipeline_templates_name" ON "pipeline_templates" ("name");
CREATE INDEX IF NOT EXISTS "idx_project_chain_targets_project" ON "project_chain_targets" ("project_id");
CREATE INDEX IF NOT EXISTS "idx_project_crons_enabled" ON "project_crons" ("enabled");
CREATE INDEX IF NOT EXISTS "idx_projects_credential_id" ON "projects" ("credential_id");
CREATE INDEX IF NOT EXISTS "idx_proxy_routes_domain" ON "proxy_routes" ("domain");
CREATE INDEX IF NOT EXISTS "idx_proxy_routes_server" ON "proxy_routes" ("server_id");
CREATE INDEX IF NOT EXISTS "idx_run_approvals_run" ON "run_approvals" ("run_id");
CREATE INDEX IF NOT EXISTS "idx_run_artifacts_run" ON "run_artifacts" ("run_id");
CREATE INDEX IF NOT EXISTS "idx_run_logs_run_seq" ON "run_logs" ("run_id", "seq");
CREATE INDEX IF NOT EXISTS "idx_run_promotions_proj" ON "run_promotions" ("project_id");
CREATE INDEX IF NOT EXISTS "idx_run_promotions_run" ON "run_promotions" ("source_run_id");
CREATE INDEX IF NOT EXISTS "idx_run_steps_run_id" ON "run_steps" ("run_id");
CREATE INDEX IF NOT EXISTS "idx_run_test_reports_run" ON "run_test_reports" ("run_id");
CREATE INDEX IF NOT EXISTS "idx_servers_credential_id" ON "servers" ("credential_id");
CREATE INDEX IF NOT EXISTS "idx_variable_groups_name" ON "variable_groups" ("name");
CREATE INDEX IF NOT EXISTS "idx_webhook_deliveries_project_id" ON "webhook_deliveries" ("project_id");
CREATE UNIQUE INDEX IF NOT EXISTS "ops_chat_calls_run" ON "ops_chat_calls" ("run_id", "ordinal");
CREATE INDEX IF NOT EXISTS "ops_chat_contexts_session" ON "ops_chat_contexts" ("session_id");
CREATE INDEX IF NOT EXISTS "ops_chat_runs_session" ON "ops_chat_runs" ("session_id", "created_at");
CREATE INDEX IF NOT EXISTS "uq_project_chain_targets" ON "project_chain_targets" ("project_id", "downstream_project_id", "branch");
CREATE TRIGGER audit_log_no_delete
BEFORE DELETE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only: DELETE forbidden');
END;

CREATE TRIGGER audit_log_no_update
BEFORE UPDATE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only: UPDATE forbidden');
END;
-- 以下 UNIQUE 约束为 squash 工具生成时遗漏,补回以保证与 PostgreSQL/MySQL 三方言一致。
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_custom_nodes_name" ON "custom_nodes" ("name");
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_pipeline_templates_name" ON "pipeline_templates" ("name");
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_project_chain_targets" ON "project_chain_targets" ("branch", "downstream_project_id", "project_id");
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_proxy_routes_domain" ON "proxy_routes" ("domain");
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_variable_groups_name" ON "variable_groups" ("name");
